#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_autop;
uniform float amzp_aSpeed;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_angle;
uniform float2 amzp_position;
uniform float2 amzp_stretch;
uniform float amzp_alpha;
uniform float amzp_hardness;
uniform float amzp_blendMode;
uniform float amzp_alphaComp;
uniform float amzp_density;
uniform float amzp_rise;
uniform float amzp_sway;
uniform float amzp_turb;
uniform float amzp_wind;
uniform float amzp_cooling;
uniform float amzp_emSize;
uniform float amzp_glow;
uniform float amzp_flick;
uniform float amzp_pops;
uniform float amzp_vig;
uniform float amzp_seed;
uniform float amzp_gradMap;
uniform float amzp_gmTri;
layout(color) uniform half4 amzp_gmFg;
layout(color) uniform half4 amzp_gmMid;
layout(color) uniform half4 amzp_gmBg;
uniform float amzp_embers;
uniform float amzp_overdrawOn;
    const float NMCUT = 0.04;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float4 layerAt(float2 uv) { return (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float TT() { return (amzp_autop>0.5) ? amzp_progress + time * amzp_aSpeed : amzp_progress; }
    float2 nmRot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float nmZ() { return max(amzp_scale * 2.0, 0.002); }
    float2 nmStd(float2 p, float pxsc) {
        p -= amzp_position * pxsc;
        p = nmRot(p, -radians(amzp_angle));
        return p / (nmZ() * max(amzp_stretch, float2(0.01)));
    }
    float2 stdFC() {
        float2 W = layer;
        float2 q = amzLayerNorm() * W - 0.5 * W;
        q.y = -q.y;
        q = nmStd(q, pxs());
        q.y = -q.y;
        return q + 0.5 * W;
    }
    float4 nmGradMap(float4 fx) {
        if (!(amzp_gradMap>0.5)) return fx;
        float3 un = fx.a > 0.0001 ? fx.rgb / fx.a : float3(0.0);
        float v = clamp(fx.a * (0.25 + 0.75 * dot(un, float3(0.299, 0.587, 0.114))), 0.0, 1.0);
        float4 pB = float4(amzp_gmBg.rgb * amzp_gmBg.a, amzp_gmBg.a), pM = float4(amzp_gmMid.rgb * amzp_gmMid.a, amzp_gmMid.a), pF = float4(amzp_gmFg.rgb * amzp_gmFg.a, amzp_gmFg.a);
        float4 c = (amzp_gmTri>0.5) ? (v < 0.5 ? mix(pB, pM, v * 2.0) : mix(pM, pF, v * 2.0 - 1.0)) : mix(pB, pF, v);
        return c;
    }
    float4 nmBlend(float4 tex, float4 fx) {
        float4 fr = clamp(fx * amzp_hardness, 0.0, 64.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 f = clamp(fx * amzp_hardness, 0.0, 1.0) * clamp(amzp_alpha, 0.0, 1.0);
        float4 b = tex * clamp(amzp_alphaComp, 0.0, 1.0);
        float4 o;
        if (int(amzp_blendMode) == 0) {
            float na = clamp((f.a - NMCUT) / (1.0 - NMCUT), 0.0, 1.0);
            o = float4(f.rgb * (na / max(f.a, 0.0001)), na);
        }
        else if (int(amzp_blendMode) == 1) o = float4(b.rgb * (f.rgb + (1.0 - f.a)), b.a);
        else if (int(amzp_blendMode) == 2) o = float4(b.rgb + f.rgb - b.rgb * f.rgb, b.a + f.a - b.a * f.a);
        else if (int(amzp_blendMode) == 4) o = float4(b.rgb + fr.rgb, max(b.a, max(f.a, max(f.r, max(f.g, f.b)))));
        else o = f + b * (1.0 - f.a);
        o = clamp(o, 0.0, 1.0);
        return float4(min(o.rgb, float3(o.a)), o.a);
    }
    float4 h43(float3 p) {
        p += float3(amzp_seed * 1.731, amzp_seed * 0.917, amzp_seed * 0.313);
        float4 p4 = fract(float4(p.xyzx) * float4(0.1031, 0.1030, 0.0973, 0.1099));
        p4 += dot(p4, p4.wzxy + 33.33);
        return fract((p4.xxyz + p4.yzzw) * p4.zywx);
    }
    float segD(float2 p, float2 a, float2 b) {
        float2 pa = p - a, ba = b - a;
        float h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-10), 0.0, 1.0);
        return length(pa - ba * h);
    }
    float3 emberRamp(float h) {
        h = clamp(h, 0.0, 1.0);
        float3 c0 = float3(0.10, 0.010, 0.0), c1 = float3(0.60, 0.05, 0.01), c2 = float3(1.0, 0.27, 0.03), c3 = float3(1.0, 0.60, 0.16), c4 = float3(1.0, 0.94, 0.76);
        if (h < 0.25) return mix(c0, c1, h * 4.0);
        if (h < 0.5) return mix(c1, c2, h * 4.0 - 1.0);
        if (h < 0.75) return mix(c2, c3, h * 4.0 - 2.0);
        return mix(c3, c4, h * 4.0 - 3.0);
    }
    float windG(float h, float2 E) {
        float hm = max(E.x * E.y, 1e-3);
        float a = h < 0.9 * hm ? -E.y * log(1.0 - h / hm) : 2.302585 * E.y + (h - 0.9 * hm) / max(0.1 * E.x, 1e-3);
        a = clamp(a, 0.0, 12.0);
        return a - 0.7 * (1.0 - exp(-a / 0.7));
    }
    float2 emPos(float a, float4 A, float4 B, float4 C, float4 D, float2 E) {
        a = max(a, 0.0);
        float y = A.y + A.z * A.w * (1.0 - exp(-a / A.w));
        float xw = D.z * (windG(y, E) - windG(A.y, E));
        xw += D.z * 0.2 * (cos(0.9 * D.w) - cos(0.9 * (D.w + a))) / 0.9;
        float g = 0.35 + 0.65 * min(a, 4.0);
        float xs = B.x * g * (sin(B.y * a + B.z) - sin(B.z));
        float gc = 0.3 + 0.7 * min(a / 2.5, 1.0);
        float2 e = D.x * gc * float2(sin(C.x * a + C.y) - sin(C.y), B.w * (cos(C.x * a + C.y) - cos(C.y)))
               + D.y * gc * float2(sin(C.z * a + C.w) - sin(C.w), -B.w * (cos(C.z * a + C.w) - cos(C.w)));
        return float2(A.x + xw + xs + e.x, y + e.y);
    }
    void nmMain() {
        float2 W = layer;
        float4 orig = layerAt(amzLayerNorm());
        float2 I = stdFC();
        float T = TT();
        float2 P = float2((I.x - 0.5 * W.x) / W.y, I.y / W.y);
        float rs = amzp_rise;
        if (rs < 0.0) { P.y = 1.0 - P.y; rs = -rs; }
        float px = 1.0 / (W.y * nmZ() * max(min(amzp_stretch.x, amzp_stretch.y), 0.01));
        float cool = max(amzp_cooling, 0.05);
        float dsz = clamp(pow(2.85 / max(amzp_density, 0.05), 0.35), 0.45, 2.0);
        float Wv = amzp_wind * 0.25;
        float tlift = 1.6 / sqrt(cool);
        float2 E = float2(0.7 * rs, tlift);
        float exc = 0.08 + 0.24 * amzp_sway + 0.12 * amzp_turb + 0.9 * abs(Wv);
        float cw = max(0.5 / max(amzp_density, 0.05), exc / 8.0);
        float cc = floor((P.x - Wv * windG(P.y, E)) / cw);
        float ncol = clamp(ceil(exc / cw), 1.0, 8.0);
        float NE = clamp(floor(amzp_embers + 0.5), 1.0, 30.0);
        float pchance = clamp(0.08 * amzp_pops, 0.0, 0.9);
        float3 col = float3(0.0);
        for (int ic = -8; ic <= 8; ic++) {
            float dc = float(ic);
            if (abs(dc) > ncol) continue;
            float ci = cc + dc;
            for (int j = 0; j < 30; j++) {
                float fj = float(j);
                if (fj >= NE) break;
                float4 s0 = h43(float3(ci, fj, 0.5));
                float Lc = mix(1.8, 4.4, s0.x) / pow(cool, 0.8);
                float Pd = Lc * mix(1.05, 1.7, s0.y);
                float tt = T / Pd + s0.z;
                float n = floor(tt);
                float age = fract(tt) * Pd;
                if (age > Lc) continue;
                float tb = T - age;
                float4 r1 = h43(float3(ci + 0.37, fj + 0.71, n));
                float4 r4 = h43(float3(ci + 0.47, fj + 0.97, n + 0.83));
                float4 A = float4((ci + r1.x) * cw, -0.08 + 0.24 * r1.y * r1.y, mix(0.35, 1.05, r1.z) * rs, tlift * mix(0.65, 1.4, r1.w));
                float popAge = Lc * mix(0.12, 0.55, r4.z);
                bool popper = r4.y < pchance;
                float rj = (popper && age > popAge && age < popAge + 0.6) ? 0.45 : 0.14;
                float yl = A.y + A.z * A.w * (1.0 - exp(-age / A.w));
                if (abs(P.y - yl) > rj + 0.11 * amzp_turb) continue;
                float4 r2 = h43(float3(ci + 0.11, fj + 0.53, n + 0.29));
                float4 r3 = h43(float3(ci + 0.83, fj + 0.19, n + 0.61));
                float4 B = float4(amzp_sway * mix(0.01, 0.04, r2.x), mix(1.3, 3.4, r2.y), r2.z * 6.28318531, r2.w < 0.5 ? -1.0 : 1.0);
                float4 C = float4(mix(1.5, 4.0, r3.x), r3.y * 6.28318531, mix(5.0, 10.0, r3.z), r3.w * 6.28318531);
                float4 D = float4(amzp_turb * mix(0.01, 0.04, r2.y * r3.x), amzp_turb * mix(0.004, 0.014, r1.w), Wv, tb);
                float2 pa = emPos(age, A, B, C, D, E);
                if (abs(P.x - pa.x) > rj || abs(P.y - pa.y) > rj) continue;
                float lf = age / Lc;
                float heat = mix(0.78, 1.0, r4.x) * pow(1.0 - lf, 0.9);
                float flash = 0.0;
                if (popper && age > popAge) {
                    float u = age - popAge;
                    heat *= 0.55;
                    flash = 2.5 * exp(-u * 16.0);
                    if (u < 0.55) {
                        float2 pp = emPos(popAge, A, B, C, D, E);
                        for (int k = 0; k < 5; k++) {
                            float fk = float(k);
                            float4 rk = h43(float3(ci + fk * 13.1, fj + 0.33, n + 0.47));
                            float an = 6.28318531 * (fk / 5.0 + 0.15 * rk.x + r4.w);
                            float2 dir = float2(cos(an), sin(an) * 0.75 + 0.3);
                            float spd = mix(0.25, 0.6, rk.y);
                            float u0 = max(u - 0.03, 0.0);
                            float2 c1 = pp + dir * spd * (1.0 - exp(-u * 5.0)) / 5.0 + float2(Wv * u, -0.12 * u * u);
                            float2 c0 = pp + dir * spd * (1.0 - exp(-u0 * 5.0)) / 5.0 + float2(Wv * u0, -0.12 * u0 * u0);
                            float rr = max(0.0018 * amzp_emSize * dsz, 0.6 * px);
                            float dk = segD(P, c0, c1);
                            float k1 = 1.0 - u / 0.55;
                            float ik = 1.4 * k1 * k1 * (0.0018 * amzp_emSize * dsz / rr) * (0.0018 * amzp_emSize * dsz / rr);
                            col += emberRamp(0.95 - u * 0.9) * ik * (exp(-dk * dk / (rr * rr)) + amzp_glow * 0.2 * exp(-dk / (2.0 * rr)));
                        }
                    }
                }
                float2 pb = emPos(age - 0.035, A, B, C, D, E);
                float r0 = mix(0.0022, 0.0062, r4.w * r4.w) * amzp_emSize * dsz * (0.45 + 0.55 * heat);
                float re = max(r0, 0.7 * px);
                float d = segD(P, pb, pa);
                float core = exp(-d * d / (re * re)) * (r0 / re) * (r0 / re);
                float halo = amzp_glow * 0.45 * exp(-d / (2.4 * re)) * (r0 / re);
                float f1 = 0.5 + 0.5 * sin(age * mix(9.0, 17.0, r3.x) + r1.x * 30.0);
                float f2 = 0.5 + 0.5 * sin(age * mix(13.0, 29.0, r3.z) + r2.x * 30.0);
                float fl = max(1.0 - amzp_flick * 0.55 * f1 * f2, 0.0) + amzp_flick * 0.9 * pow(0.5 + 0.5 * sin(age * mix(4.0, 9.0, r2.w) + r3.w * 40.0), 14.0);
                float fade = smoothstep(0.0, 0.08, age) * (1.0 - smoothstep(0.82, 1.0, lf));
                float br = (0.12 + 1.6 * heat * heat) * fl * fade + flash * fade;
                col += emberRamp(heat) * br * (core + halo);
            }
        }
        float xn = P.x / max(0.5 * W.x / W.y, 0.01);
        col *= mix(1.0, clamp(1.15 - 0.75 * xn * xn, 0.0, 1.0), clamp(amzp_vig, 0.0, 1.0));
        float3 c = clamp(col, 0.0, 16.0);
        float4 G = float4(c, clamp(max(c.r, max(c.g, c.b)), 0.0, 1.0));
        amzOutput = nmBlend(orig, nmGradMap(G));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
